  "networks": {
    "default": {
      "name": "codeplus-w1-batch2-leader-20260923_default",
      "ipam": {}
    }
  },
  "services": {
    "etcd": {
      "command": [
        "etcd",
        "-advertise-client-urls=http://etcd:2379",
        "-listen-client-urls",
        "http://0.0.0.0:2379",
        "--data-dir",
        "/etcd"
      ],
      "entrypoint": null,
      "environment": {
        "ETCD_AUTO_COMPACTION_MODE": "revision",
        "ETCD_AUTO_COMPACTION_RETENTION": "1000",
        "ETCD_QUOTA_BACKEND_BYTES": "4294967296",
        "ETCD_SNAPSHOT_COUNT": "50000"
      },
      "healthcheck": {
        "test": [
          "CMD",
          "etcdctl",
          "endpoint",
          "health"
        ],
        "timeout": "5s",
        "interval": "5s",
        "retries": 30
      },
      "image": "quay.io/coreos/etcd:v3.5.25",
      "networks": {
        "default": null
      },
      "volumes": [
        {
          "type": "volume",
          "source": "etcd",
          "target": "/etcd",
          "volume": {}
        }
      ]
    },
    "minio": {
      "command": [
        "minio",
        "server",
        "/data",
        "--console-address",
        ":9001"
      ],
      "entrypoint": null,
      "healthcheck": {
        "test": [
          "CMD",
          "curl",
          "-f",
          "http://localhost:9000/minio/health/live"
        ],
        "timeout": "5s",
        "interval": "5s",
        "retries": 30
      },
      "image": "quay.io/minio/minio:RELEASE.2024-12-18T13-15-44Z",
      "networks": {
        "default": null
      },
      "volumes": [
        {
          "type": "volume",
          "source": "minio",
          "target": "/data",
          "volume": {}
        }
      ]
    },
    "standalone": {
      "command": [
        "milvus",
        "run",
        "standalone"
      ],
      "depends_on": {
        "etcd": {
          "condition": "service_healthy",
          "required": true
        },
        "minio": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "entrypoint": null,
      "environment": {
        "ETCD_ENDPOINTS": "etcd:2379",
        "MINIO_ADDRESS": "minio:9000",
        "MQ_TYPE": "woodpecker"
      },
      "healthcheck": {
        "test": [
          "CMD",
          "curl",
          "-f",
          "http://localhost:9091/healthz"
        ],
        "timeout": "5s",
        "interval": "5s",
        "retries": 60,
        "start_period": "1m0s"
      },
      "image": "milvusdb/milvus:v3.0.1",
      "networks": {
        "default": null
      },
      "ports": [
        {
          "mode": "ingress",
          "host_ip": "127.0.0.1",
          "target": 19530,
          "published": "19542",
          "protocol": "tcp"
        },
        {
          "mode": "ingress",
          "host_ip": "127.0.0.1",
          "target": 9091,
          "published": "9103",
          "protocol": "tcp"
        }
      ],
      "security_opt": [
        "seccomp:unconfined"
      ],
      "volumes": [
        {
          "type": "volume",
          "source": "milvus",
          "target": "/var/lib/milvus",
          "volume": {}
        }
      ]
    }
  },
  "volumes": {
    "etcd": {
      "name": "codeplus-w1-batch2-leader-20260923_etcd"
    },
    "milvus": {
      "name": "codeplus-w1-batch2-leader-20260923_milvus"
    },
    "minio": {
      "name": "codeplus-w1-batch2-leader-20260923_minio"
    }
  }
}

